import Cocoa

/// Vendor logos from Lobe Icons (https://icons.lobehub.com, MIT), rendered to 96 px PNG and embedded
/// so the page needs no network and no resource files. OpenAI and Grok are the mono set (a
/// template image, tinted to the text colour so it follows light / dark); Claude and Gemini
/// are the colour set.
enum AIIcons {
    static func image(for vendor: AIVendor) -> NSImage? {
        switch vendor {
        case .chatgpt: return make(openai, template: true)
        case .claude:  return make(claude, template: false)
        case .grok:    return make(grok, template: true)
        case .gemini:  return make(gemini, template: false)
        }
    }

    private static var cache: [String: NSImage] = [:]

    private static func make(_ base64: String, template: Bool) -> NSImage? {
        if let hit = cache[base64] { return hit }
        guard let data = Data(base64Encoded: base64), let image = NSImage(data: data) else { return nil }
        image.size = NSSize(width: 48, height: 48)      // 96 px at 2x: sharp on Retina
        image.isTemplate = template
        cache[base64] = image
        return image
    }

    private static let openai =
        ""

    private static let claude =
        ""

    private static let grok =
        ""

    private static let gemini =
        ""
}
